namespace docking;







using docking.action;
using docking.actions;

/**
 * A class that can be used as an interface for using actions associated with keybindings. This
 * class is meant to only by used by internal Ghidra key event processing.
 */
public abstract class DockingKeyBindingAction : AbstractAction {

	protected Tool tool;
	protected DockingActionIf dockingAction;
	protected KeyStroke keyStroke;

	public DockingKeyBindingAction(Tool tool, DockingActionIf action, KeyStroke keyStroke) : base(KeyBindingUtils.parseKeyStroke(keyStroke))
    {
		this.tool = tool;
		this.dockingAction = action;
		this.keyStroke = keyStroke;
	}

	/* @Override */
	public bool isEnabled() {
		return true; // always enable; this is a internal action that cannot be disabled
	}

	public abstract ExecutableAction getExecutableAction(Component focusOwner);

	public bool isSystemKeybindingPrecedence() {
		return false;
	}

	protected ActionContext getLocalContext(ComponentProvider localProvider) {
		if (localProvider == null) {
			return new DefaultActionContext();
		}

		ActionContext context = localProvider.getActionContext(null);
		if (context == null) {
			context = new DefaultActionContext(localProvider);
		}

		context.setContextProvider(localProvider);
		return context;
	}

	public List<DockingActionIf> getActions() {
		return List.of(dockingAction);
	}

}
